package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/avroschema/go-avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parser.go <source_file_name> <struct_name>")
		os.Exit(1)
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	// Read the entire source file into memory
	file, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", sourceFileName, err)
		return
	}

	// Parse the JSON representation of the struct
	var structDef map[string]interface{}
	json.Unmarshal(file, &structDef)

	// Extract the fields and their types from the struct definition
	fields := make(map[string]schema.Field)
	for fieldName, fieldVal := range structDef {
		switch v := fieldVal.(type) {
		case map[string]interface{}:
			// Handle nested maps (arrays or objects)
			for _, subField := range v {
				subFieldStr, _ := json.Marshal(subField)
				_, fieldType := getAvroTypeFromJSONSubField(subFieldStr)
				fields[fieldName+".field"+strconv.Itoa(len(v))].AddField(fieldType)
			}
		default:
			// Handle scalar values
			fields[fieldName].SetSchema(getAvroTypeFromJSONScalarValue(fieldName, fieldVal))
		}
	}

	// Generate Avro schema as a string
	schemaString, err := schema.Generate(fields)
	if err != nil {
		fmt.Printf("Failed to generate Avro schema: %v\n", err)
		return
	}

	// Write the generated Avro schema to a new file
	outputFilePath := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outputFilePath, []byte(schemaString), 0644)
	if err != nil {
		fmt.Printf("Error writing to file %s: %v\n", outputFilePath, err)
		return
	}

	fmt.Printf("Generated Avro schema saved to %s.avsc\n", structName)
}

// Helper function to convert JSON value to Avro type
func getAvroTypeFromJSONScalarValue(name string, val interface{}) *schema.Schema {
	switch v := val.(type) {
	case int:
		return schema.Int()
	case float64:
		return schema.Float()
	case bool:
		return schema.Boolean()
	case string:
		return schema.String()
	default:
		return schema.Unknown()
	}
}

// Helper function to handle arrays of scalars
func getAvroTypeFromArray(val []interface{}) *schema.Array {
	typeArr := schema.Array()
	for i, v := range val {
		typeArr.AddField(getAvroTypeFromJSONScalarValue(fmt.Sprintf("arrayElement%v", i), v))
	}
	return &typeArr
}

// Helper function to handle object structures recursively
func getAvroTypeFromJSONMap(mapVal map[string]interface{}) *schema.Map {
	typeObj := schema.Object()
	for key, val := range mapVal {
		field := getAvroTypeFromJSONScalarValue(key, val)
		typeObj.AddField(field)
	}
	return &typeObj
}

// Helper function to handle unknown types
func getAvroTypeFromUnknown() *schema.Unknown {
	return &schema.Unknown{}
}
```

